import type {ChatSession} from '../../../types/session.js';
import type {
  SessionCreateOptions,
  SessionCursor,
  SessionListOptions,
  SessionStore,
  SessionSummary,
  StoreCannotList,
} from '../../../types/sessionStore.js';
import type {CollectionLike, MongoClientLike} from './mongoDriverTypes.js';
import type {MongoSessionDocument} from './mongoSessionDocument.js';
import {persistedFields, toChatSession, toSessionSummary} from './mongoSessionDocument.js';
import {cappedLimit, cursorAt} from '../sessionListWindow.js';

const DEFAULT_COLLECTION_NAME = 'hal_sessions';
// Entries are left out so a page of summaries never carries a conversation out of the database.
const SUMMARY_FIELDS = {_id: 1, createdAt: 1, updatedAt: 1, entryCount: 1} as const;
// Eight hours, matching InMemorySessionStore: a bound on the cache in front of the collection, not a retention period.
const DEFAULT_MAX_AGE_MS = 8 * 60 * 60 * 1000;

interface CachedSession {
  session: ChatSession;
  cachedAt: number;
}

interface SharedOptions {
  collectionName?: string;
  now?: () => Date;
  maxAgeMs?: number;
}

export type MongoSessionStoreOptions = SharedOptions &
  (
    | {collection: CollectionLike<MongoSessionDocument>}
    | {client: MongoClientLike; dbName: string}
    | {url: string; dbName: string}
  );

export class MongoSessionStore implements SessionStore {
  private readonly cache = new Map<string, CachedSession>();
  private readonly options: MongoSessionStoreOptions;
  private readonly now: () => Date;
  private readonly maxAgeMs: number;
  private opened: Promise<CollectionLike<MongoSessionDocument>> | undefined;
  private owned: MongoClientLike | undefined;

  constructor(options: MongoSessionStoreOptions) {
    this.options = options;
    this.now = options.now ?? (() => new Date());
    this.maxAgeMs = options.maxAgeMs ?? DEFAULT_MAX_AGE_MS;
  }

  async create(sessionId: string, userId: string | number, options?: SessionCreateOptions): Promise<ChatSession> {
    const session: ChatSession = {
      sessionId,
      userId,
      entries: [],
      authHeaders: options?.authHeaders,
      workspaceId: options?.workspaceId,
    };
    const collection = await this.collection();
    const startedAt = this.now();
    await collection.updateOne(
      {_id: sessionId},
      {$set: {...persistedFields(session), createdAt: startedAt, updatedAt: startedAt}},
      {upsert: true}
    );

    // Cached only once the write landed: a failing database would otherwise fill memory with sessions it never stored.
    this.remember(sessionId, session);
    return session;
  }

  async get(sessionId: string): Promise<ChatSession | undefined> {
    const cached = this.cache.get(sessionId);
    if (cached !== undefined && !this.hasAged(cached)) return cached.session;
    // Dropped on a stale read too: a document erased elsewhere would otherwise leave its entry cached for good.
    this.cache.delete(sessionId);

    const collection = await this.collection();
    const document = await collection.findOne({_id: sessionId});
    if (document === null) return undefined;

    const session = toChatSession(document);
    this.remember(sessionId, session);
    return session;
  }

  // The consumer's erasure primitive, which the engine never calls: it removes the document, not just the cache.
  delete(sessionId: string): Promise<boolean> {
    return this.eraseConversation(sessionId);
  }

  // The engine evicts only a session no client ever received, so its document holds nothing worth keeping.
  evict(sessionId: string): Promise<boolean> {
    return this.eraseConversation(sessionId);
  }

  async count(): Promise<number> {
    const collection = await this.collection();
    return collection.countDocuments();
  }

  // Empties the cache alone; eraseAll is the durable wipe, so neither can be reached by accident.
  clear(): void {
    this.cache.clear();
  }

  async save(session: ChatSession): Promise<void> {
    const collection = await this.collection();
    await collection.updateOne(
      {_id: session.sessionId},
      {$set: {...persistedFields(session), updatedAt: this.now()}, $setOnInsert: {createdAt: this.now()}},
      {upsert: true}
    );
  }

  /** One query, filtered on the user in the database and sorted on the index `latestFor` already needs. */
  async listFor(userId: string | number, options?: SessionListOptions): Promise<SessionSummary[]> {
    const limit = cappedLimit(options?.limit);
    // Never issued as a query: mongo reads `limit: 0` as no limit at all, which is the opposite of what it asks for.
    if (limit === 0) return [];

    const collection = await this.collection();
    if (collection.find === undefined) {
      throw new StoreCannotList();
    }

    const documents = await collection
      .find(olderThan(userId, options?.before), {
        sort: {updatedAt: -1, _id: -1},
        limit,
        projection: SUMMARY_FIELDS,
      })
      .toArray();
    return documents.map(toSessionSummary);
  }

  /** The user's most recently saved conversation, by `updatedAt`, read through `get` so a live one is the object its running turn writes to. */
  async latestFor(userId: string | number): Promise<ChatSession | undefined> {
    const collection = await this.collection();
    const latest = await collection.findOne({userId}, {sort: {updatedAt: -1, _id: -1}, projection: {_id: 1}});
    return latest === null ? undefined : this.get(latest._id);
  }

  /** Erases one conversation permanently and drops it from the cache. */
  async eraseConversation(sessionId: string): Promise<boolean> {
    this.cache.delete(sessionId);
    const collection = await this.collection();
    const {deletedCount} = await collection.deleteOne({_id: sessionId});
    return deletedCount > 0;
  }

  /** Erases every conversation created strictly before `cutoff`, and returns how many went. */
  async eraseOlderThan(cutoff: Date): Promise<number> {
    this.cache.clear();
    const collection = await this.collection();
    const {deletedCount} = await collection.deleteMany({createdAt: {$lt: cutoff}});
    return deletedCount;
  }

  /** Erases every conversation this store can see. */
  async eraseAll(): Promise<number> {
    this.cache.clear();
    const collection = await this.collection();
    const {deletedCount} = await collection.deleteMany({});
    return deletedCount;
  }

  /** Closes the driver only when this store opened it; a supplied client stays the caller's to close. */
  async close(): Promise<void> {
    this.cache.clear();
    if (this.owned === undefined) return;

    await this.owned.close();
    this.owned = undefined;
    this.opened = undefined;
  }

  // Dropping a stale entry erases nothing: the collection is the truth and the next get reloads from it.
import {validateMessage} from './validation.js';

// One wire name for the client frame: the alias is gone, and the frame the validator returns is the exported shape.

describe('the websocket frame validator', () => {
  it('accepts user_message and returns the frame the exported union describes', () => {
    const result = validateMessage({type: 'user_message', content: 'hello'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  it('rejects send_message, which is no longer a wire name', () => {
    const result = validateMessage({type: 'send_message', content: 'hello'});

    expect(result).toEqual({valid: false, error: 'Unknown message type: send_message'});
  });

  it('drops any field the frame does not define, rather than forwarding it', () => {
    const result = validateMessage({type: 'user_message', content: 'hello', chatId: 'c1'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  // [validated by: accepts a bare list_sessions frame and rejects malformed pagination without calling listFor](../../specs/hal-engine-conversation-list/spec.md#over-the-websocket-protocol)
  it('accepts list_sessions pagination', () => {
    const valid = validateMessage({
      type: 'list_sessions',
      limit: 10,
      before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's1'},
      userId: 'another-user',
    });
    expect({valid, bare: validateMessage({type: 'list_sessions'})}).toEqual({
      valid: {
        valid: true,
        data: {
          type: 'list_sessions',
          limit: 10,
          before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's1'},
        },
      },
      bare: {valid: true, data: {type: 'list_sessions'}},
    });
  });

  it('rejects malformed list_sessions fields', () => {
    for (const [field, value] of [
      ['limit', '10'],
      ['limit', -1],
      ['limit', 1.5],
      ['before', 'not-an-object'],
      ['before', {updatedAt: 'not-a-date', sessionId: 's1'}],
      ['before', {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: ''}],
    ] as const) {
      const result = validateMessage({type: 'list_sessions', [field]: value});
      expect(result).toEqual({valid: false, error: expect.stringContaining(field)});
    }
  });

  // [validated by: accepts an optional integer limit from 1 through 200](../../specs/hal-engine-conversation-list/spec.md#over-the-websocket-protocol)
  it('rejects list_sessions limits outside the protocol range', () => {
    expect([0, 201].map(limit => validateMessage({type: 'list_sessions', limit}))).toEqual([
      {valid: false, error: 'list_sessions limit must be an integer from 1 to 200'},
      {valid: false, error: 'list_sessions limit must be an integer from 1 to 200'},
    ]);
  });

  // [validated by: accepts list_conversations pagination with an ISO cursor](../../specs/hal-engine-conversation-list/spec.md#over-the-websocket-protocol)
  it('accepts list_conversations pagination with an ISO cursor', () => {
    expect(
      validateMessage({
        type: 'list_conversations',
        limit: 20,
        before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's1'},
        userId: 'ignored',
      })
    ).toEqual({
      valid: true,
      data: {
        type: 'list_conversations',
        limit: 20,
        before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's1'},
      },
    });
  });
});
  error: (category, message) => process.stderr.write(line('error', category, message)),
};

const engine = createHalEngine({
  // REQUIRED: AI provider settings
  provider: {
    type: 'bedrock', // 'bedrock' | 'vertex' | 'openai' | 'anthropic' | 'mock'
    region: 'eu-west-1',
    modelId: 'eu.anthropic.claude-sonnet-4-5-20250929-v1:0',
    maxTokens: 4096, // REQUIRED for bedrock
  },

  // REQUIRED: System prompt configuration. Every field but `identity` is optional.
  prompt: {
    identity: 'You are a helpful assistant.',
    domainContext: 'You help users with weather and general questions.',
    responseGuidelines: 'Be concise. Use tools when available.',
    toolPreamble: 'Replaces the built-in instructions telling the model when to call a tool.',
  },

  // REQUIRED: Authentication. `ws` receives the upgrade request; return null to reject it.
  auth: {
    ws: async () => ({id: 'user-1'}),
    http: authMiddleware,
  },

  // OPTIONAL: Tool registry
  tools: toolRegistry,

  // OPTIONAL: Session store (defaults to InMemorySessionStore)
  session: sessionStore,

  // OPTIONAL: Transport settings
  transport: {
    port: 8086, // 0 lets the OS choose; unset falls through to PORT, then 8086
    corsOrigin: ['https://example.com'],
    // basePath defaults to '/hal' and the heartbeat to 30s.
    basePath: '/hal',
    heartbeatIntervalMs: 30_000,
    resume: {enabled: true, latest: true}, // rejoin by ?sessionId= or the user's latest; ?new=1 starts one
    history: {enabled: true}, // authenticated sockets may request summaries
    additionalRoutes: router => router.get('/ping', (_req, res) => res.json({ok: true})),
    rootRoutes: router => router.get('/', (_req, res) => res.send('<h1>Hello</h1>')),
    errorHandler: (err, _req, res, _next) => res.status(500).json({error: String(err)}), // replaces Express's default HTML error page
  },

  // OPTIONAL: Orchestrator settings
  orchestrator: {
    maxToolRounds: 5, // Max tool rounds executed (default 5); the provider is called at most maxToolRounds + 1 times
    contextConfig: {
      // How many messages are kept, and how much of each.
      maxMessages: 50,
      maxContentLength: 4000,
    },
    toolTimeoutMs: 30_000, // Abandon a tool call after this long, answering the model with a timeout result (default 30000; 0 = no deadline)
    hooks,
  },

  // OPTIONAL: Logger. Process-wide, not per engine - see docs/logging.md.
  logger: myLogger,

const harness = (chunks: MessageChunk[], {failWith, pauseAfter}: StreamScript = {}) => {
  const sent: OutgoingMessage[] = [];
  const ws = {send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;

  const stream = async function* (): AsyncGenerator<MessageChunk> {
    for (const [position, chunk] of chunks.entries()) {
      if (pauseAfter && position === pauseAfter.chunks) await pauseAfter.until;
      yield chunk;
    }
    if (failWith) throw failWith;
  };

  const processMessageStream = jest.fn(stream);
  const orchestrator = {processMessageStream} as unknown as ChatOrchestrator;
  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};

  const handle = createMessageHandler(orchestrator);

  return {
    session,
    processMessageStream,
    sent,
    frames: () => wire(sent),
    send: (raw: unknown = {type: 'user_message', content: 'hello'}, signal?: AbortSignal) =>
      handle(ws, session, raw, signal),
  };
};

describe('the websocket message handler', () => {
  describe('dispatch', () => {
